import {office} from './trading-office.js?v=20261003autonomy11';
const root=document.getElementById('trading-app');let csrf='',state=null,tab='office',selected='scout',initialised=false,search='',filter='all',stopOffice=null,polling=false,zoomOpen=false,pendingCommand=null;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const usd=x=>new Intl.NumberFormat('es-ES',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(x||0);
const money=x=>new Intl.NumberFormat('es-ES',{style:'currency',currency:state?.book?.currency||'EUR',maximumFractionDigits:2}).format(x||0);
const number=x=>new Intl.NumberFormat('es-ES').format(x||0);
const cap=x=>x>=1e9?(x/1e9).toFixed(2)+' B USD':Math.round(x/1e6)+' M USD';
