function brief(x,n=220){const t=String(x||'');return t.length>n?t.slice(0,n).replace(/\s+\S*$/,'')+'…':t;}
const activeWork=w=>['pending','running','blocked'].includes(w.status);
const workOrder=(a,b)=>Number(b.status==='running')-Number(a.status==='running')||Number(a.status==='blocked')-Number(b.status==='blocked')||(a.notBefore||a.createdAt)-(b.notBefore||b.createdAt);
const workLabels={research:'Contrastar fuentes',analysis:'Analizar candidata',risk:'Revisar riesgo',execution:'Preparar ejecución',strategy:'Mejorar estrategia',code:'Desarrollar mejora'};
const workStatus={pending:'En cola',running:'En curso',blocked:'Pendiente de datos',complete:'Completado',failed:'Incidencia'};
export function employeeWorkView(s,id){const actor=s.company?.agency?.actors?.[id],jobs=(s.company?.agency?.workQueue||[]).filter(w=>w.owner===id),active=jobs.filter(activeWork).sort(workOrder),latest=jobs.filter(w=>w.finishedAt&&w.result).sort((a,b)=>b.finishedAt-a.finishedAt)[0],agent=s.agents?.find(a=>a.id===id),freshDecision=!latest||(actor?.lastAction?.time||0)>=latest.finishedAt,nextTask=active[0]?.task||(freshDecision?actor?.nextTask:'')||(latest?'Encargo completado; decidir la siguiente tarea útil.':agent?.task)||'Sin encargo pendiente';return {actor,active,latest,operational:!!(active.length||latest),currentTask:agent?.status==='trabajando'?agent.task:nextTask,nextTask,result:latest?.result||actor?.lastAction?.result||'',resultAt:latest?.finishedAt||actor?.lastAction?.time||0};}
export function officeSummary(s){const c=s.company||{},m=c.meetings?.find(m=>m.status==='completa'),p=c.pipeline,events=(s.events||[]).filter(e=>!['descartado','caducado'].includes(e.status)),work=(c.agency?.workQueue||[]).filter(activeWork).sort(workOrder),counts=p?.counts||{signals:events.length,researchQueue:events.filter(e=>e.preScore?.eligible&&!e.confirmed).length,confirmed:events.filter(e=>e.confirmed).length,analysisReady:events.filter(e=>e.confirmed&&!e.plan).length,riskPending:events.filter(e=>e.plan&&!e.review).length,plansPrepared:events.filter(e=>e.plan).length,approvedWaiting:events.filter(e=>e.plan&&e.review?.approve&&e.status==='espera').length,supportPending:work.filter(w=>w.phase==='preliminary'||['strategy','code'].includes(w.kind)).length},goals=work.slice(0,3).map(w=>({text:w.task||workLabels[w.kind],owner:w.owner,due:w.notBefore?date(w.notBefore):null}));const current=!!p||events.length>0||work.length>0,fallback=counts.approvedWaiting?'Hay '+counts.approvedWaiting+' planes aprobados esperando condiciones de entrada.':counts.analysisReady?'Pedro tiene '+counts.analysisReady+' candidatas contrastadas para analizar.':counts.researchQueue?'Hay '+counts.researchQueue+' candidatas filtradas en cola para contrastar.':'El radar busca señales que superen los filtros.';return {m,counts,pipeline:p,status:s.runtimeUnavailable?'Incidencia: los ciclos recientes no están confirmados.':s.paused?'Nuevas entradas pausadas.':p?.blocker||(current?fallback:m?.chair?.officeStatus||brief(m?.chair?.summary)||fallback),concern:current?(counts.researchQueue?'Evitar repetir búsquedas sin fuentes nuevas; completar la evidencia antes de aprobar entradas.':'Revisar riesgo, vigilar precios de entrada y conservar el presupuesto.'):m?.chair?.concerns||'Preservar el presupuesto y evitar compras sin evidencia suficiente.',expectations:current?(p?.nextSessionDate?'Preparar la sesión del '+p.nextSessionDate+'; las entradas requieren aprobación y una referencia reciente.':'Preparar decisiones contrastadas antes de la próxima sesión.'):m?.chair?.expectations||'Preparar decisiones contrastadas y aprender con paciencia.',goals:goals.length?goals:(m?.chair?.goals||[]).map(g=>({text:g.title,owner:g.owner,due:g.dueDate})).concat((c.tasks||[]).map(t=>({text:t.task,owner:t.owner,due:null}))).slice(0,3)};}
export function sessionPreparation(s){const p=s.company?.sessionPlan,pipeline=s.company?.pipeline;return {date:p?.date||pipeline?.nextSessionDate||null,ready:p?.ready||(s.events||[]).filter(e=>e.plan&&e.review?.approve&&e.status==='espera').map(e=>({eventId:e.id,symbol:e.symbol,...e.plan,conditions:e.reasons||[]})),steps:p?.steps||[],notes:(s.events||[]).filter(e=>e.preliminary||e.preRisk).sort((a,b)=>Math.max(b.preliminary?.at||0,b.preRisk?.at||0)-Math.max(a.preliminary?.at||0,a.preRisk?.at||0)).map(e=>({id:e.id,symbol:e.symbol,analysis:e.preliminary,risk:e.preRisk})).slice(0,3)};}
function sessionPreparationHtml(){const p=sessionPreparation(state),day=p.date?date(p.date+'T13:30:00Z').replace(/,?\s+\d{2}:\d{2}$/,''):'';return '<h4>Próxima sesión'+(day?' · '+esc(day):'')+'</h4>'+(p.ready.length?p.ready.slice(0,3).map(e=>'<p><b>'+esc(e.symbol)+'</b> · plan preparado<br>Entrada '+usd(e.entryMin)+'–'+usd(e.entryMax)+' · stop '+usd(e.stop)+' · objetivo '+usd(e.target)+'<br><small>'+esc(brief((e.conditions||[]).join(' · '),170))+'</small></p>').join(''):'<p>Aún no hay entradas listas. El equipo puede investigar y comparar candidatas con el mercado cerrado.</p>')+(p.steps.length?'<p><b>Siguiente paso:</b> '+esc(brief(p.steps[0],180))+'</p>':'')+(p.notes.length?'<h4>Trabajo preliminar</h4>'+p.notes.map(e=>'<p><b>'+esc(e.symbol)+'</b> · '+esc(brief(e.analysis?.summary||e.risk?.summary,170))+'<br><small>'+esc(brief([...(e.analysis?.missingEvidence||[]),...(e.risk?.missingEvidence||[])].join(' · '),140))+' · pendiente de aprobación</small></p>').join(''):'');}
function rentDate(){const p=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Madrid',year:'numeric',month:'numeric'}).formatToParts(new Date()).map(p=>[p.type,p.value]));return new Intl.DateTimeFormat('es-ES',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Madrid'}).format(new Date(Date.UTC(+p.year,+p.month,0,12)));}
function summaryContent(){return officeSummary(state);}
function renderSummary(){const el=root.querySelector('#ao-summary');if(!el)return;const x=summaryContent();el.innerHTML='<button class="ao-panel ao-summary-card" data-open="status"><small>ESTADO GENERAL</small><h3>'+ (state.runtimeUnavailable?'Revisar incidencia':state.paused?'En pausa':'Equipo en marcha')+'</h3><p>'+esc(brief(x.status))+'</p><span>'+number(x.counts.analysisReady)+' listas para análisis · '+number(x.counts.approvedWaiting)+' planes aprobados ↗</span></button><button class="ao-panel ao-summary-card" data-open="goals"><small>OBJETIVOS CORTO PLAZO</small><h3>Las próximas prioridades</h3><p>'+esc(brief(x.goals[0]?.text||'Pendientes del próximo acuerdo del equipo',140))+'</p><span>'+esc(x.goals[0]?.due||'Reuniones · 11:00 y 22:30')+' ↗</span></button><button class="ao-panel ao-summary-card" data-open="rent"><small>PRÓXIMO PAGO DE ALQUILER</small><h3>'+esc(rentDate())+'</h3><p>'+money(state.operating?.remainingEur??10)+' disponibles de 10 € de IA este mes.</p><span>Presupuesto y gasto ↗</span></button>';el.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openOfficePanel(b.dataset.open));}
function ownEmployeeSummary(id){const v=employeeWorkView(state,id),a=v.actor;if(!a)return '';const agent=state.agents.find(x=>x.id===id);return '<p><b>Mi objetivo:</b> '+esc(brief(v.operational?agent?.objective||a.goal:a.goal,200))+'</p>'+(v.result?'<p><b>Último resultado:</b> '+esc(brief(v.result,230))+'<br><small>'+date(v.resultAt)+'</small></p>':'')+'<small>Próxima iniciativa: '+date(a.nextWake)+' · '+a.runs+' iniciativas · '+Number(a.costEur||0).toFixed(4)+' € de IA'+(a.inbox?.filter(m=>m.status==='pendiente').length?' · '+a.inbox.filter(m=>m.status==='pendiente').length+' encargos pendientes':'')+'</small>';}
function openOfficePanel(id){const dialog=document.createElement('dialog');dialog.className='ao-office-dialog';const x=summaryContent(),a=state.agents.find(a=>a.id===id);let title='',html='';if(a){selected=id;const work=employeeWorkView(state,id);title=a.name+' · '+a.role;html='<p class="ao-dialog-status">'+esc(a.status==='trabajando'?a.status:work.active[0]?workStatus[work.active[0].status]:a.status)+'</p><p>'+esc(brief(work.currentTask,240))+'</p>'+ownEmployeeSummary(id)+'<p><b>Su estilo:</b> '+esc(a.personality||'Perspectiva propia según su rol')+'</p><small>Última actividad real: '+date(a.lastRun)+'</small><details><summary>Ficha, historial y controles</summary><div id="ao-detail"></div></details>';}else if(id==='goals'){title='Objetivos corto plazo';html=x.goals.map(g=>'<p><b>'+esc(state.agents.find(a=>a.id===g.owner)?.name||g.owner)+'</b> · '+esc(g.text)+'<br><small>'+esc(g.due||'Sin fecha acordada todavía')+'</small></p>').join('')||'<p>La próxima reunión fijará prioridades. No hay objetivos acordados todavía.</p>';html+='<p>Próximas reuniones: 11:00 y 22:30 · Madrid.</p>'; }else if(id==='portfolio'){title='Inversiones y próximos planes';html='<p>Patrimonio ficticio: <b>'+money(state.equity)+'</b> · efectivo '+money(state.book.cash)+'.</p><p>Resultado: <b>'+money(state.equity-state.book.initial)+'</b>.</p>'+(state.book.positions.length?state.book.positions.map(p=>'<p><b>'+esc(p.symbol)+'</b> · '+p.qty+' acciones<br>Entrada '+usd(p.entry)+' · referencia '+usd(p.mark)+'<br>Stop '+usd(p.stop)+' · objetivo '+usd(p.target)+'</p>').join(''):'<p>Sin posiciones abiertas. El equipo continúa investigando; no se fuerza una compra para llenar la cartera.</p>')+sessionPreparationHtml()+'<button data-goto="portfolio">Ver cartera y diario completo</button>'; }else if(id==='rent'){title='Alquiler y gastos';html='<p>Próximo vencimiento: <b>'+esc(rentDate())+'</b>.</p><p>Saldo real para IA: <b>'+money(state.operating?.remainingEur??10)+'</b> / 10 € mensuales.</p><p>'+number(Math.floor(state.operating?.unitsRemaining??10000))+' unidades de funcionamiento restantes.</p><p>El beneficio ficticio no recarga el saldo real. Al agotarlo, se detiene la IA; las salidas por reglas continúan.</p>';}else if(id==='minutes'){title='Mesa de minutas e informes';html='<p>'+esc(brief(state.company?.reports?.[0]?.text,650)||'Aún no hay informe registrado.')+'</p>'+(x.m?.chair?.decisions||[]).slice(0,4).map(d=>'<p><b>'+esc(d.title)+'</b><br>'+esc(brief(d.reason,160))+'</p>').join('')+'<button data-goto="company">Abrir archivo de reuniones</button>';}else{title=id==='boss'?'Despacho de César':'Estado general';html='<p>'+esc(x.status)+'</p><p><small>'+number(x.counts.researchQueue)+' investigaciones en cola · '+number(x.counts.analysisReady)+' candidatas listas para análisis · '+number(x.counts.approvedWaiting)+' planes aprobados · '+number(x.counts.supportPending)+' encargos de preparación</small></p><p><b>Qué preocupa al equipo:</b> '+esc(x.concern)+'</p><p><b>Expectativas:</b> '+esc(x.expectations)+'</p><p>Patrimonio ficticio: <b>'+money(state.equity)+'</b> · '+state.book.positions.length+' posiciones.</p><button data-goto="portfolio">Cartera y resultados</button> <button data-goto="settings">Conexiones y ajustes</button>';}dialog.innerHTML='<header><h3>'+esc(title)+'</h3><button data-close aria-label="Cerrar panel">✕</button></header><div class="ao-setting-body">'+html+'</div>';root.append(dialog);if(a)detail();dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>{dialog.close();root.querySelector('[data-tab="'+b.dataset.goto+'"]').click();});dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();}
function updateOffice(){renderSummary();renderLiveBoards();for(const a of state.agents){const b=root.querySelector('[data-agent="'+a.id+'"]');if(b)b.innerHTML='<small><i class="ao-dot"></i>'+esc(a.status)+'</small><b>'+esc(a.name)+'</b><small>'+esc(a.role)+'</small>';}detail();}
function zoomOffice(){zoomOpen=true;stopOffice?.();stopOffice=null;const dialog=document.createElement('dialog');dialog.className='ao-zoom-dialog';dialog.innerHTML='<header><b>La oficina de César</b><button data-close>Cerrar ✕</button></header><canvas class="ao-office"></canvas>';root.append(dialog);dialog.showModal();const stop=office(dialog.querySelector('canvas'),()=>state,openOfficePanel);dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{stop();dialog.remove();zoomOpen=false;renderBody();});}
function detail(){const target=root.querySelector('#ao-detail');if(!target)return;
if(selected==='boss'){target.innerHTML='<div class="ao-agent-detail"><div class="ao-avatar">C</div><small>DIRECCIÓN</small><h3>César</h3><p>Tu despacho. Tú controlas las conexiones, el presupuesto y las reglas del equipo.</p><button id="ao-boss-settings">Configurar OpenAI y datos</button><button id="ao-boss-portfolio">Ver cartera y operaciones</button><button id="ao-boss-pause">'+(state.paused?'Reanudar entradas':'Pausar nuevas entradas')+'</button></div>';target.querySelector('#ao-boss-settings').onclick=()=>root.querySelector('[data-tab="settings"]').click();target.querySelector('#ao-boss-portfolio').onclick=()=>root.querySelector('[data-tab="portfolio"]').click();target.querySelector('#ao-boss-pause').onclick=()=>action('control',{paused:!state.paused});return;}
const a=state.agents.find(a=>a.id===selected);if(!a)return;const models={scout:'Luna · fuentes primarias y catalizadores; filtros sin tokens',analyst:'Luna para análisis habituales; Sol sólo en casos complejos, máximo 2 al día',risk:'Luna y límites deterministas de riesgo',operator:'Motor de órdenes sin tokens; Luna para decisiones y propuestas en reuniones',auditor:'KPIs y reglas por código; Luna como máximo una auditoría de cierres al día',designer:'Luna para debate y código · pruebas y despliegue automático · solo Agent Office'};
const logs=state.logs.filter(l=>l.agent===a.id&&l.mode==='real').slice(0,5);const work=employeeWorkView(state,a.id),tasks=work.active.slice(0,4);
target.innerHTML=`<div class="ao-agent-detail"><div class="ao-avatar">${esc(a.name.slice(0,1))}</div><small>${esc(a.role.toUpperCase())} · ${esc(a.status.toUpperCase())}</small><h3>${esc(a.name)}</h3><p><b>Ahora:</b> ${esc(brief(work.currentTask,260))}</p><p>${esc(models[a.id])}</p><p><b>Objetivo:</b> ${esc(a.objective)}</p><p>${esc(a.personality)}</p><p>Última actividad: ${date(a.lastRun)}</p><h4>Mis propuestas y memoria</h4>${(state.company?.memory?.[a.id]||[]).slice(-3).reverse().map(m=>'<p>'+esc(m.day)+' · '+esc(m.idea)+'<br>'+esc(m.uncertainty)+'</p>').join('')||'<p>Su criterio propio quedará registrado en las reuniones.</p>'}<h4>Últimos resultados reales</h4>${(work.latest?'<p>'+esc(work.latest.result)+'<br><small>'+date(work.latest.finishedAt)+'</small></p>':'')+logs.map(l=>'<p>'+esc(l.text)+'</p>').join('')||'<p>Todavía no hay resultados registrados.</p>'}<h4>Cola de trabajo</h4>${tasks.map(w=>'<p><b>'+esc(state.events.find(e=>e.id===w.eventId)?.symbol||workLabels[w.kind]||w.kind)+'</b> · '+esc(workStatus[w.status])+'<br>'+esc(brief(w.task,180))+'<br><small>'+(w.phase==='preliminary'?'Preparación preliminar · ':'')+date(w.notBefore)+'</small></p>').join('')||'<p>Sin encargos operativos pendientes.</p>'}<button id="ao-agent-pause">${a.paused?'Activar agente':'Pausar agente'}</button><button id="ao-agent-events">Ver evidencia y decisiones</button>${a.id==='operator'?'<p>Pausar Yari también detiene los cierres automáticos. El botón global solo pausa nuevas entradas.</p>':''}</div>`;
target.querySelector('#ao-agent-pause').onclick=e=>action('agent',{id:a.id,paused:!a.paused},e.currentTarget);target.querySelector('#ao-agent-events').onclick=()=>root.querySelector('[data-tab="'+(a.id==='designer'?'radar':a.id==='auditor'||a.id==='operator'?'portfolio':'events')+'"]').click();}
function universeRows(){const needle=search.toLowerCase();const assets=state.assets.filter(a=>(a.symbol+' '+a.name+' '+a.sector).toLowerCase().includes(needle)&&(filter==='all'||filter==='primary'&&a.marketCap<=state.config.primaryCap||filter==='secondary'&&a.marketCap>state.config.primaryCap||filter==='contracts'&&a.dataVerified)).sort((a,b)=>a.marketCap-b.marketCap);root.querySelector('#ao-universe-table').innerHTML=table(['EMPRESA','BOLSA','CAPITALIZACIÓN','PRECIO DE CATÁLOGO','DATOS'],assets.slice(0,150).map(a=>`<tr><td><b>${esc(a.symbol)}</b><small>${esc(a.name)} · ${esc(a.sector)}</small></td><td>${a.exchange}</td><td>${cap(a.marketCap)}<small>${a.marketCap<=state.config.primaryCap?'Prioridad small cap':'Lista secundaria'}</small></td><td>${usd(a.price)}</td><td><span class="ao-chip ${a.dataVerified?'ok':'pending'}">${state.mode==='demo'?'Ficticio':a.dataVerified?'Identidad contrastada':'Esperando referencia'}</span></td></tr>`),'No hay empresas con esos filtros.')+`<div class="ao-setting-body"><p>${number(assets.length)} coincidencias. Se muestran las primeras 150; usa la búsqueda para localizar cualquier empresa.</p></div>`;}
function eventForm(event){const target=root.querySelector('#ao-event-form');target.innerHTML=`<article class="ao-panel" style="margin-top:18px"><header class="ao-panel-head"><h3>Investigación del catalizador · aportación opcional</h3><small>FUENTE PRIMARIA</small></header><form class="ao-setting-body" id="ao-event"><div class="ao-fields"><div><label>Símbolo</label><input name="symbol" required value="${esc(event?.symbol||'')}" maxlength="8"></div><div><label>Fecha y hora confirmadas (tu zona local)</label><input type="datetime-local" name="date" required></div><div><label>Tipo de evento</label><input name="kind" value="${esc(event?.kind||'Resultados')}" required></div><div><label>Enlace a la fuente</label><input name="source" type="url" placeholder="https://… relaciones con inversores" value="${esc(event?.source||'')}" required></div></div><label>Evidencia: anuncio, datos financieros y razones para estudiar la empresa</label><textarea name="summary" minlength="50" maxlength="12000" required placeholder="Copia los hechos relevantes de la fuente. El analista rechazará una tesis que no pueda justificar con esta evidencia.">${esc(event?.summary||'')}</textarea><label class="ao-check"><input type="checkbox" name="confirmed" required>He contrastado la fecha y los hechos con la fuente enlazada.</label><button class="ao-primary">Guardar para el analista</button><p>Santi investiga automáticamente con Luna y búsqueda web: busca fechas, documentos de la empresa y catalizadores. Esta ficha permite corregir o añadir información si tú quieres. Las estimaciones de probabilidad e impacto son hipótesis, no garantías ni estadísticas calibradas.</p></form></article>`;
  if(event?.date){const d=new Date(event.date);target.querySelector('[name="date"]').value=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
  target.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await action('event',{symbol:f.get('symbol'),date:new Date(f.get('date')).toISOString(),kind:f.get('kind'),source:f.get('source'),summary:f.get('summary'),confirmed:f.get('confirmed')==='on'},e.currentTarget.querySelector('button'));};}
function settings(){const c=state.config;const body=root.querySelector('#ao-body');body.innerHTML=`<article class="ao-panel ao-start"><header class="ao-panel-head"><h3>Para empezar con datos reales</h3><small>LA CARTERA PERMANECE VACÍA HASTA TENER SEÑALES VÁLIDAS</small></header><div class="ao-setting-body"><ol><li>Crea una clave en <a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">OpenAI Platform</a>, activa la facturación de API y guárdala aquí.</li><li>Las cotizaciones públicas se consultan automáticamente en Cloudflare; no necesitas Gateway, PC encendido ni clave de datos.</li><li>Deja a Santi investigar los candidatos: contrastará fuentes primarias y fechas, y propondrá escenarios. Puedes ampliar sus fichas en Oportunidades si quieres.</li><li>Pedro analiza, María revisa y Yari abre el registro ficticio solo si pasan todos los controles. El programador continúa cada cinco minutos.</li></ol><p>La investigación de Santi funciona con OpenAI; las entradas necesitan además una referencia reciente durante la sesión, identidad contrastada y evidencia suficiente. La conversión EUR/USD usa una referencia diaria del BCE, no una cotización de cambio ejecutable.</p><p>Referencia EUR/USD: ${state.book.fx?esc(state.book.fx.rate)+' USD por EUR · '+esc(state.book.fx.date):'pendiente'}.</p></div></article><div class="ao-settings"><article class="ao-panel"><header class="ao-panel-head"><h3>Conexiones</h3><small>SOLO PROPIETARIO</small></header><div class="ao-setting-body"><div class="ao-connection"><b>OpenAI</b><span class="ao-chip ${state.connections.openai?'ok':'pending'}">${state.connections.openai?'Configurado':'Pendiente'}</span></div><div class="ao-connection"><b>Yahoo Finance · referencia pública</b><span class="ao-chip ${state.connections.market?'ok':'pending'}">${state.connections.market?'Datos disponibles':'Pendiente / fuera de sesión'}</span></div><div class="ao-connection"><b>Programador</b><span class="ao-chip">${state.automatic?'Habilitado · 5 min':'Detenido'}</span></div><p>Último ciclo: ${date(state.lastTick)}. Última consulta de datos: ${date(state.connections.marketCheckedAt)}. ${esc(state.connections.marketStatus)} ${esc(state.connections.marketError||'')}</p><form id="ao-key-form"><label>Clave de la API de OpenAI</label><input id="ao-key" type="password" autocomplete="new-password" placeholder="sk-…" required minlength="20" maxlength="300"><p>Se cifra en el servicio privado y nunca se devuelve al navegador. Al guardarla, los ciclos pueden consumir hasta ${usd(c.dailyBudget)} al día, con un presupuesto total de 10 € por mes. Necesitas saldo de API en OpenAI; una suscripción de ChatGPT no proporciona ese saldo.</p><button class="ao-primary" ${state.connections.encryption?'':'disabled'}>Guardar clave</button><button type="button" id="ao-delete-key">Eliminar clave</button></form><p>${state.connections.encryption?'Cifrado del servicio configurado.':'Falta configurar el cifrado del servicio. No introduzcas la clave aún.'}</p></div></article><article class="ao-panel"><header class="ao-panel-head"><h3>Datos y ejecución de referencia</h3><small>100% CLOUDFLARE · SIN PC</small></header><div class="ao-setting-body"><p>Yahoo Finance se consulta cada 15 minutos durante la sesión de EE. UU. para posiciones y hasta ocho candidatos finalistas. Se conserva la fecha original del proveedor. Las referencias pueden llevar retraso.</p><p>Las operaciones ficticias usan el precio observado, más 0,25% de deslizamiento estimado por lado y 1 USD de comisión. No se inventa un bid/ask ni se afirma que ese precio fuera ejecutable. Los stops se comprueban en cada consulta; pueden saltarse entre consultas y cerrarse más allá del umbral.</p><p>Liquidez: promedio de hasta 20 sesiones completas. El spread no está disponible; el deslizamiento es una hipótesis de simulación. Se rechazan referencias de más de 35 minutos, descargas de más de 20 minutos o instrumentos sin identidad válida. No se opera fuera de la sesión.</p><p>Fuente pública sin garantía de disponibilidad. Si bloquea consultas o devuelve errores, se conservan los datos con su fecha y se detiene la ejecución que necesite precios válidos. No requiere clave ni suscripción de datos.</p></div></article><article class="ao-panel"><header class="ao-panel-head"><h3>Universo, modelos y presupuesto</h3><small>FILTROS GLOBALES</small></header><form id="ao-config" class="ao-setting-body"><div class="ao-fields">${[['minCap','Capitalización mínima (M USD)',c.minCap/1e6,50,500,1],['primaryCap','Máximo prioritario (M USD)',c.primaryCap/1e6,500,3000,1],['maxCap','Máximo secundario (M USD)',c.maxCap/1e6,1000,5000,1],['minPrice','Precio mínimo (USD)',c.minPrice,1,20,.1],['minDollarVolume','Volumen negociado mínimo (M USD)',c.minDollarVolume/1e6,1,20,.1],['dailyBudget','Presupuesto IA diario (USD)',c.dailyBudget,.1,10,.1],['riskPct','Riesgo por posición (%)',c.riskPct,.1,1,.05],['maxEntries','Entradas máximas por sesión',c.maxEntries,1,2,1],['maxPositions','Posiciones máximas',c.maxPositions,1,20,1],['horizonDays','Ventana de catalizadores (días)',c.horizonDays,7,45,1]].map(([name,label,value,min,max,step])=>`<div><label for="ao-${name}">${label}</label><input id="ao-${name}" name="${name}" type="number" value="${value}" min="${min}" max="${max}" step="${step}" required></div>`).join('')}</div><button class="ao-primary">Guardar límites</button><p><b>Alquiler mensual:</b> 10 € reales = 10.000 unidades internas. Restan ${money(state.operating?.remainingEur??10)} y ${state.operating?.daysLeft||0} días. Este límite mensual también se comprueba antes de reservar cada llamada.</p><p><b>Uso eficiente:</b> Luna para investigación, análisis habituales, riesgo y coordinación; Pedro usa Sol sólo para casos complejos, con un máximo de dos análisis profundos al día. Santi investiga hasta ${state.policy?.researchDailyLimit||12} candidatos al día, espaciados al menos ${state.policy?.researchIntervalMinutes||30} minutos, únicamente si superan el radar por código. Se guardan las fichas para no repetir búsquedas durante 24 horas. Los filtros y la ejecución no llaman a modelos. El presupuesto incluye llamadas de búsqueda web.</p><p>Asignación por tramos: 500 €, 750 €, 1.000 € y +250 € por cada 5.000 € adicionales de patrimonio. Máximo 20 empresas; acciones enteras y comisión incluidas en el presupuesto del lote. Si el stop supera el riesgo permitido, se rechaza la entrada. Pérdida diaria máxima: ${c.dailyLossPct}%. La liquidez se filtra por promedio histórico; no mide la profundidad del mercado.</p></form></article><article class="ao-panel"><header class="ao-panel-head"><h3>Operación del laboratorio</h3><small>CONTROL HUMANO</small></header><div class="ao-setting-body"><p>La cartera empieza vacía con 10.000 € ficticios. No se generan precios, empresas ni operaciones de demostración. El barrido cubre cuatro fechas por ciclo hasta completar la ventana de ${c.horizonDays} días.</p><button id="ao-auto">${state.automatic?'Detener ciclos automáticos':'Activar ciclos automáticos'}</button><p>Los ciclos siguen ejecutándose aunque cierres esta página. Detenerlos detiene también la vigilancia por el programador; las cotizaciones también se detienen al deshabilitarlos.</p><p>Las llamadas de IA se reservan antes de empezar. Si una petición termina sin confirmar su consumo, se conserva esa reserva para evitar superar el presupuesto.</p><p>Los resultados de cartera incluyen costes de ejecución estimados. El coste real de IA, datos y alojamiento debe evaluarse por separado antes de concluir que existe rentabilidad.</p><p>Santi puede buscar documentos de la empresa y SEC mediante búsqueda web. Las fechas sin una fuente consultada quedan pendientes y no permiten entrar. Próximos módulos: pruebas históricas y comparación con un benchmark. Augusto revisa KPIs y cuellos de botella; puede proponer cambios de estrategia, coordinación y análisis. Cadaqui prepara cambios reales del código de Agent Office, con pruebas, registro, despliegue y reversión. El presupuesto y las demás secciones de la web quedan protegidos.</p></div></article></div>`;
  root.querySelector('#ao-key-form').onsubmit=async e=>{e.preventDefault();const input=root.querySelector('#ao-key');const key=input.value;input.value='';const j=await action('key',{key},e.currentTarget.querySelector('button'));if(j)renderBody();};root.querySelector('#ao-delete-key').onclick=async()=>{await action('key',{key:''});renderBody();};
  root.querySelector('#ao-config').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries([...new FormData(e.currentTarget)].map(([k,v])=>[k,Number(v)*(['minCap','primaryCap','maxCap','minDollarVolume'].includes(k)?1e6:1)]));await action('config',values,e.currentTarget.querySelector('button'));};root.querySelector('#ao-auto').onclick=async e=>{await action('control',{automatic:!state.automatic},e.currentTarget);renderBody();};
}

function renderLiveBoards(){const el=root.querySelector('#ao-live-boards');if(!el)return;const k=state.kpis||{},v=state.visual;el.dataset.focus=v?.focus||'pipeline';el.innerHTML='<article class="ao-panel ao-live-panel" style="margin-top:18px"><header class="ao-panel-head"><h3>Cadaqui · panel vivo</h3><small>V'+(v?.version||1)+'</small></header><div class="ao-setting-body"><p>'+esc(v?.summary||'Esperando sincronización del próximo ciclo')+'</p><div class="ao-kpi-row"><span>P/L menos IA</span><b>'+ (k.netAfterAi==null?'Cambio pendiente':money(k.netAfterAi))+'</b></div><div class="ao-kpi-row"><span>Equivalencia neta 1:1.000</span><b>'+ (k.efficiencyNet==null?'Pendiente':money(k.efficiencyNet))+'</b></div><div class="ao-kpi-row"><span>Candidatos priorizados</span><b>'+number(k.qualified)+'</b></div><p>Capital ficticio y costes reales se muestran por separado. La equivalencia es tu objetivo de eficiencia, no un beneficio real.</p><button id="ao-live-radar">Abrir KPIs y comunicación</button></div></article>';el.innerHTML+=ceoReport();el.querySelector('#ao-live-radar').onclick=()=>root.querySelector('[data-tab="radar"]').click();el.querySelector('[data-company-open]')?.addEventListener('click',()=>root.querySelector('[data-tab="company"]').click());}
function renderRadar(body){const k=state.kpis||{},d=state.discovery||{},g=state.governance||{},policy=state.policy||{},o=state.operating||{};const ratio=x=>x==null?'—':(x*100).toFixed(1)+'%';const scalar=x=>x==null?'—':Number(x).toFixed(2);const rows=state.events.filter(e=>e.preScore).sort((a,b)=>b.preScore.score-a.preScore.score).slice(0,35);body.innerHTML=
'<div class="ao-metrics">'+[['ALQUILER MENSUAL',money(o.remainingEur??10),number(Math.floor(o.unitsRemaining??10000))+' unidades restantes'],['COBERTURA DEL ALQUILER',(o.rentCoveragePct||0).toFixed(1)+'%',money(o.benefitEquivalent)+' equivalentes / 10 €'],['P/L MENOS IA',k.netAfterAi==null?'Pendiente':money(k.netAfterAi),'Cambio BCE actual aproximado'],['EQUIVALENCIA NETA',k.efficiencyNet==null?'Pendiente':money(k.efficiencyNet),'1.000 € ficticios = 1 € de objetivo'],['IA ACUMULADA',usd(k.aiUsd),'Reservas pendientes: '+money(k.reservedEur)],['CIERRES / ACIERTOS',number(k.closed)+' / '+ratio(k.winRate),'Factor de beneficio '+scalar(k.profitFactor)],['INVESTIGACIONES',number(k.researched),'Descartadas '+number(k.rejected)]].map(([label,value,note])=>'<article class="ao-metric"><small>'+label+'</small><strong>'+value+'</strong><span>'+note+'</span></article>').join('')+'</div>'+
'<article class="ao-panel"><header class="ao-panel-head"><h3>Radar de Santi · primero señales, después IA</h3><small>'+number(d.universe||state.universe.eligible)+' EMPRESAS · '+number(d.enriched)+' FICHAS</small></header><div class="ao-setting-body"><p>Alquiler: 10 € reales al mes = 10.000 unidades de funcionamiento. El ritmo se adapta al saldo y los días restantes; al agotarse se pausa IA y siguen las salidas por código. Se renueva mensualmente, conservando la cartera. Beneficio ficticio no recarga saldo real de OpenAI. Catálogo diario, SEC 8-K y PR Newswire cada 15 minutos, calendario de cuatro fechas por barrido. Se enriquecen cuatro empresas por ciclo; métricas SEC en caché siete días e histórico seis horas. No se llama a IA si no hay señales con prioridad ≥ '+(policy.minScore||45)+'.</p>'+Object.entries(d.sources||{}).map(([name,s])=>'<p><b>'+esc(name)+'</b> · '+date(s.at)+' · '+(s.error?esc(s.error):number(s.items)+' documentos, '+number(s.matched)+' coincidencias')+'</p>').join('')+'</div>'+table(['EMPRESA / PRIORIDAD','SEÑAL Y MOTIVOS','SALUD / VALORACIÓN ANUAL','MERCADO HISTÓRICO'],rows.map(e=>{const p=state.profiles?.[e.symbol],m=p?.fundamentals?.metrics||{},h=p?.market||{},r=e.preScore;return '<tr><td><b>'+esc(e.symbol)+' · '+r.score+'/100</b><small>'+ (r.eligible?'En cola de Santi':'No supera filtros')+'</small></td><td>'+esc(e.signal?.headline||e.title)+'<small>'+esc(r.reasons.join(' · '))+'<br>'+esc(r.warnings.join(' · '))+'</small></td><td>PER '+scalar(m.pe)+' · P/B '+scalar(m.pb)+' · EV/EBITDA '+scalar(m.evToEbitda)+'<small>FCF '+(m.fcf==null?'—':usd(m.fcf))+' · deuda/EBITDA '+scalar(m.debtToEbitda)+'<br>Margen '+ratio(m.netMargin)+' · ROE '+ratio(m.roe)+'<br>Ingresos YoY '+ratio(m.revenueYoY)+' · CAGR 3a '+ratio(m.revenueCagr3y)+'<br>Periodo '+esc(m.annualEnd||'sin datos')+' · '+r.coverage+' métricas disponibles'+(p?.fundamentals?.source?'<br><a target="_blank" rel="noreferrer" href="'+safeLink(p.fundamentals.source)+'">Datos SEC ↗</a>':'')+'</small></td><td>1 mes '+ratio(h.return21d)+' · 3 meses '+ratio(h.return63d)+'<small>Beta vs SPY '+scalar(h.beta1y)+' · Sharpe '+scalar(h.sharpe1yZeroRiskFree)+'<br>Volumen relativo '+scalar(h.relativeVolume)+'<br>'+esc((p?.errors||[]).join(' · '))+'</small></td></tr>';}),'Sin señales puntuadas todavía; el siguiente barrido no inventará candidatas.')+'<div class="ao-setting-body"><p>Prioridad no es probabilidad de subir. Ratios anuales, EBITDA aproximado, muestras sectoriales parciales; bancos usan reglas distintas. Datos ausentes se muestran —. Insider ownership no disponible. Histórico sin ajuste de splits/dividendos; las caídas se contrastan antes de operar.</p></div></article>'+
'<article class="ao-panel" style="margin-top:18px"><header class="ao-panel-head"><h3>Augusto · mejora diaria</h3><small>REGLAS V'+(policy.version||1)+'</small></header><div class="ao-setting-body"><p>Umbral '+(policy.minScore||45)+' · hasta '+(policy.researchDailyLimit||12)+' investigaciones/día · intervalo '+(policy.researchIntervalMinutes||30)+' min. Riesgo '+state.config.riskPct+'%.</p><p>'+esc(g.reviews?.[0]?.summary||'Pendiente de primera revisión diaria')+'</p><p>Con suficiente evidencia puede endurecer filtros, reducir riesgo o frecuencia. Cada cambio tiene siete días de observación y reversión por deterioro tras diez cierres nuevos. No aumenta presupuesto, exposición ni entradas. Los cambios no prueban causalidad o rentabilidad.</p>'+ (g.changes||[]).map(c=>'<p><b>'+esc(c.action)+' · '+esc(c.status)+'</b> · '+date(c.time)+'<br>'+esc(c.reason)+'<br>Prioridad '+c.before.policy.minScore+' → '+c.after.policy.minScore+' · riesgo '+c.before.riskPct+' → '+c.after.riskPct+'</p>').join('')+'</div></article>'+
'<article class="ao-panel" style="margin-top:18px"><header class="ao-panel-head"><h3>Comunicación entre empleados</h3><small>MENSAJES DEL FLUJO REAL</small></header><div class="ao-log">'+(g.messages||[]).slice(0,20).map(m=>'<article><small>'+date(m.time)+' · '+esc(state.agents.find(a=>a.id===m.from)?.name||m.from)+' → '+esc(state.agents.find(a=>a.id===m.to)?.name||m.to)+'</small><p>'+esc(m.text)+'</p></article>').join('')+'</div></article><p class="ao-footer">'+esc(k.limitations)+'</p>';
}

function ceoReport(){const r=state.company?.reports?.[0];return '<article class="ao-panel ao-ceo-report" style="margin-top:18px"><header class="ao-panel-head"><h3>Informe para César</h3><small>'+ (r?date(r.time):'11:00 / 22:30')+'</small></header><div class="ao-setting-body"><p>'+esc(r?.text||'El equipo entregará aquí el informe de sus reuniones diarias.')+'</p>'+ (r?'<p>Hoy: '+money(r.pnlToday)+' ficticios · '+r.closedToday+' cierres · '+money(r.costToday)+' de IA. Alquiler restante '+money(r.rentRemaining)+'.</p>':'')+'<button data-company-open>Ver reuniones y decisiones</button></div></article>';}
function renderCompany(body){const wasOpen=body.querySelector('#ao-archive')&&!body.querySelector('#ao-archive').hidden;body.innerHTML='<article class="ao-panel"><header class="ao-panel-head"><h3>Minutas e informe</h3><small>11:00 / 22:30 · Madrid</small></header><div class="ao-setting-body"><p>'+esc(state.company?.meetings?.find(m=>m.status==='completa')?.chair?.summary||'Pendiente de la próxima reunión.')+'</p><button id="ao-show-archive">Consultar actas, propuestas y cambios</button></div></article><div id="ao-archive" hidden></div>';body.querySelector('#ao-show-archive').onclick=()=>{const el=body.querySelector('#ao-archive');el.hidden=!el.hidden;if(!el.hidden)renderCompanyArchive(el);};if(wasOpen){const el=body.querySelector('#ao-archive');el.hidden=false;renderCompanyArchive(el);}}
function renderCompanyArchive(body){const c=state.company||{},v=c.versions?.[0],ui=c.ui||{};body.dataset.companyTheme=ui.theme||'violet';body.innerHTML='<article class="ao-panel"><header class="ao-panel-head"><h3>'+esc(ui.headline||'La empresa de César')+'</h3><small>DOS REUNIONES DIARIAS · MADRID</small></header><div class="ao-setting-body"><p>11:00 · planificación y prioridades. 22:30 · cierre, aprendizaje e informe diario. Los seis empleados plantean ideas independientes y después debaten las propuestas con Luna; Augusto contrasta y decide; Cadaqui implementa programas de oficina con pruebas y versiones. Las reuniones se guardan por fases para no repetir llamadas.</p><p>Máximo 0,025 € por reunión, ajustado al presupuesto restante. Estrategias nuevas: siete días de observación, veinte cierres nuevos y cien observaciones antes de evaluar su activación. La empresa simulada prioriza paciencia, evidencia y eficiencia. Su objetivo mensual es cubrir 10.000 unidades de alquiler con 10.000 € de beneficio ficticio a la escala 1.000:1. Es una meta ambiciosa, no una promesa; agotar los 10 € reales detiene la IA. Cada empleado interpreta su preocupación y motivación como parte de un personaje ficticio, conservando criterio y propuestas propias.</p><p>La autonomía permite replantear todo el código de lógica, coordinación, análisis y diseño dentro de Agent Office. El presupuesto, el carácter ficticio del dinero y la seguridad de la web son condiciones permanentes. Los parches reales pasan por pruebas aisladas, control de ámbito, versionado, publicación y reversión.</p></div></article>'+ceoReport()+
(c.evidenceProtocol?'<article class="ao-panel" style="margin-top:18px"><header class="ao-panel-head"><h3>Prueba de evidencia · observación</h3><small>SIN CAMBIAR ENTRADAS</small></header><div class="ao-setting-body"><p>'+esc(c.evidenceProtocol.note)+'</p>'+c.evidenceProtocol.groups.map(g=>'<p>'+esc(g.status)+' · '+g.count+' candidatas · '+money(g.knownCostEur)+' de IA registrada · '+g.unknownCosts+' costes anteriores sin desglose.</p>').join('')+'</div>'+table(['EMPRESA','ESTADO','MOTIVO','COSTE REGISTRADO'],c.evidenceProtocol.rows.map(r=>'<tr><td>'+esc(r.symbol)+'</td><td>'+esc(r.status)+'</td><td>'+esc(r.reason)+'</td><td>'+(r.costEur===null?'—':money(r.costEur))+'</td></tr>'),'Sin muestra todavía')+'</article>':'')+
'<article class="ao-panel" style="margin-top:18px"><header class="ao-panel-head"><h3>Tareas acordadas</h3></header><div class="ao-setting-body">'+(c.tasks||[]).map(t=>'<p><b>'+esc(state.agents.find(a=>a.id===t.owner)?.name||t.owner)+'</b> · '+esc(t.task)+'</p>').join('')+'</div></article>'+
(c.meetings||[]).slice(0,8).map(m=>'<article class="ao-panel ao-meeting" style="margin-top:18px"><header class="ao-panel-head"><h3>'+esc(m.day)+' · '+esc(m.scheduledTime||m.slot)+'</h3><small>'+esc(m.status)+' · '+new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR',minimumFractionDigits:4,maximumFractionDigits:4}).format(m.costEur||0)+'</small></header><div class="ao-setting-body">'+(m.error||m.reason?'<p>'+esc(m.error||m.reason)+'</p>':'')+(m.voices||[]).map(v=>'<details><summary>'+esc(v.name)+' · '+esc(v.idea)+'</summary><p><b>Hechos:</b> '+esc(v.facts)+'</p><p><b>Respuesta al equipo:</b> '+esc(v.replyTo)+'</p><p><b>Incertidumbre:</b> '+esc(v.uncertainty)+'</p><p><b>Siguiente tarea:</b> '+esc(v.nextTask)+'</p><p>Evidencia: '+esc((v.evidence||[]).join(', '))+'</p></details>').join('')+(m.responses?.length?'<h4>Debate · segunda ronda</h4>'+m.responses.map(v=>'<details><summary>'+esc(state.agents.find(a=>a.id===v.agent)?.name||v.name)+' · '+esc(v.replyTo||v.idea)+'</summary><p>'+esc(v.idea)+'</p><p>Incertidumbre: '+esc(v.uncertainty)+'</p></details>').join(''):'')+(m.chair?'<h4>Decisión conjunta · Augusto</h4><p>'+esc(m.chair.summary)+'</p>'+m.chair.decisions.map(d=>'<p><b>'+esc(d.title)+' · '+esc(d.kind)+'</b><br>'+esc(d.reason)+'<br>Validación: '+esc(d.successMetric)+' · revisar en '+d.reviewDays+' días.</p>').join(''):'<p>Esperando acta de Augusto.</p>')+'</div></article>').join('')+
'<article class="ao-panel" style="margin-top:18px"><header class="ao-panel-head"><h3>Desarrollo autónomo de Cadaqui</h3><small>CÓDIGO REAL · PRUEBAS · DESPLIEGUE</small></header><div class="ao-setting-body"><p>Augusto puede encargar cambios completos de lógica, coordinación, análisis y diseño de Agent Office. Cadaqui prepara código; GitHub ejecuta las pruebas sin red ni credenciales y publica o revierte. Presupuesto, contabilidad y acceso permanecen protegidos.</p>'+((c.development||[]).map(j=>'<details><summary>'+esc(j.status)+' · '+date(j.time)+'</summary><p>'+esc(j.summary)+'</p><p>'+esc(j.error||'')+'</p><p>Archivos: '+esc(j.edits.map(e=>e.file).join(' · '))+'</p>'+(j.commit?'<a href="https://github.com/CesarSGZ/CesarHomeLab/commit/'+j.commit+'" target="_blank" rel="noopener">Ver código publicado</a>':'')+'</details>').join('')||'<p>No hay parches pendientes. Los empleados conocen su autonomía; no se fuerzan cambios sin utilidad.</p>')+'</div></article>'+
'<article class="ao-panel" style="margin-top:18px"><header class="ao-panel-head"><h3>Código de oficina y experimentos</h3><small>VERSIONES Y REVERSIÓN</small></header><div class="ao-setting-body">'+(c.versions||[]).slice(0,10).map(v=>'<details><summary>v'+v.version+' · '+esc(v.status)+' · '+date(v.time)+'</summary><p>'+esc(v.program.rationale)+'</p><p>'+esc(v.gate||'Programa validado')+' · '+v.observations+' observaciones.</p><p>Pruebas: '+esc(v.tests.join(' · '))+'</p><pre class="ao-program-code">'+esc(v.source)+'</pre><button data-code-download="'+v.id+'">Descargar módulo de estrategia</button></details>').join('')+'</div></article>';
body.querySelectorAll('[data-company-open]').forEach(b=>b.onclick=()=>body.querySelector('.ao-meeting')?.scrollIntoView({behavior:'smooth'}));body.querySelectorAll('[data-code-download]').forEach(b=>b.onclick=()=>{const v=c.versions.find(v=>v.id===b.dataset.codeDownload);const url=URL.createObjectURL(new Blob([v.source],{type:'text/javascript'}));const a=document.createElement('a');a.href=url;a.download='agent-office-strategy-v'+v.version+'.mjs';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
function chart(){const canvas=root.querySelector('#ao-chart');if(!canvas)return;canvas.width=900;canvas.height=180;const ctx=canvas.getContext('2d');const points=state.book.curve;if(!points.length)return;const min=Math.min(...points.map(p=>p.value))* .999,max=Math.max(...points.map(p=>p.value))*1.001;ctx.strokeStyle='#7e959630';for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(40,20+i*45);ctx.lineTo(870,20+i*45);ctx.stroke();}ctx.strokeStyle='#a99bd2';ctx.lineWidth=2;ctx.beginPath();points.forEach((p,i)=>{const x=40+i/Math.max(1,points.length-1)*830,y=155-(p.value-min)/Math.max(1,max-min)*125;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();ctx.fillStyle='#82929c';ctx.font='12px monospace';ctx.fillText(money(max),40,16);ctx.fillText(money(min),40,174);}
async function refresh(force=false){if(polling)return;polling=true;try{state=await api('status');state.runtimeUnavailable=state.connections.serviceHealthy===false||(state.lastTick&&Date.now()-state.lastTick>15*60e3);if(state.runtimeUnavailable){state.busy=false;state.agents=state.agents.map(a=>({...a,status:'incidencia',task:'Ciclos sin confirmar. Última tarea registrada: '+a.task}));}if(!root.querySelector('#ao-body'))shell();renderHeader();if(force||tab==='office'||tab==='portfolio')(stopOffice||zoomOpen?updateOffice():renderBody());else if(tab==='universe')universeRows();else if(tab==='radar')renderRadar(root.querySelector('#ao-body'));else if(tab==='company')renderCompany(root.querySelector('#ao-body'));}catch(e){if(!state)root.innerHTML=`<div class="ao-error"><h2>Agent Office</h2><p>${esc(e.message)}</p><p>El módulo privado necesita que el servicio y la migración estén desplegados. Vuelve a intentarlo después del despliegue.</p><button id="ao-retry">Volver a intentar</button></div>`;root.querySelector('#ao-retry')?.addEventListener('click',()=>refresh(true));feedback(e.message,true);}finally{polling=false;}}
async function initialise(token){if(initialised)return;initialised=true;csrf=token;await refresh(true);setInterval(()=>{if(document.getElementById('trading')?.classList.contains('active')&&!document.hidden)refresh();},6000);}
window.TradingLab={initialise};window.addEventListener('homelab:trading-init',e=>initialise(e.detail));if(window.TradingLabPending)initialise(window.TradingLabPending);
window.addEventListener('homelab:view',e=>{if(e.detail==='trading'&&initialised)refresh(true);});
